"""Consolidate identical pure GN fields without changing their expressions.

Only fixed-name attribute reads, position/index fields and an explicit list of
stateless scalar/vector operations and read-only geometry queries are eligible.
Geometry-producing operations, group calls and zone state remain distinct.
There is no algebraic simplification. A structural certificate checks every
retained opaque consumer and every zone pairing.
"""
from collections import deque
import hashlib
import json
import math


PURE_PROPERTIES = {
    'ShaderNodeMath': ('operation', 'use_clamp'),
    'ShaderNodeVectorMath': ('operation',),
    'ShaderNodeCombineXYZ': (), 'ShaderNodeSeparateXYZ': (),
    'FunctionNodeCompare': ('data_type', 'operation', 'mode'),
    'FunctionNodeBooleanMath': ('operation',),
    # The geometry input remains an opaque expression identity. Queries of
    # different geometry cannot be shared even if their fields match.
    'GeometryNodeSampleIndex': ('data_type', 'domain', 'clamp'),
    'GeometryNodeAttributeStatistic': ('data_type', 'domain'),
    'GeometryNodeAttributeDomainSize': ('component',),
    'GeometryNodeAccumulateField': ('data_type', 'domain'),
    'GeometryNodeSwitch': ('input_type',),
}


def constant(value):
    if isinstance(value, float): return ('float', value.hex())
    if isinstance(value, (int, bool, str)) or value is None: return (type(value).__name__, value)
    if hasattr(value, 'as_pointer'): return ('ID', value.as_pointer())
    return tuple(constant(item) for item in value)


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


class Index:
    def __init__(self, tree):
        self.tree = tree; self.nodes = list(tree.nodes); self.links = list(tree.links)
        self.incoming = {node: [] for node in self.nodes}
        self.outgoing = {node: [] for node in self.nodes}
        self.socket_links = {}
        self.output_indices = {socket: i for node in self.nodes for i, socket in enumerate(node.outputs)}
        for link in self.links:
            self.incoming[link.to_node].append(link)
            self.outgoing[link.from_node].append(link)
            self.socket_links.setdefault(link.to_socket, []).append(link)
        predecessors = {node: [link.from_node for link in self.incoming[node]] for node in self.nodes}
        self.pairs = []
        for node in self.nodes:
            other = getattr(node, 'paired_output', None)
            if other is not None:
                predecessors[node].append(other); predecessors[other].append(node)
                self.pairs.append((node, other))
        pending = [node for node in self.nodes if node.bl_idname == 'NodeGroupOutput']
        self.live = set()
        while pending:
            node = pending.pop()
            if node in self.live: continue
            self.live.add(node); pending.extend(predecessors[node])

    def inputs(self, node, tokens):
        values = []
        for socket in node.inputs:
            links = self.socket_links.get(socket, ())
            value = (('links', tuple((tokens[link.from_node], self.output_indices[link.from_socket]) for link in links))
                     if links else ('default', constant(getattr(socket, 'default_value', None))))
            values.append((socket.identifier, socket.bl_idname, value))
        return tuple(values)

    def pure(self, node):
        if node.mute: return None
        if node.bl_idname == 'GeometryNodeSwitch' and node.input_type not in ('FLOAT', 'INT', 'BOOLEAN', 'VECTOR'):
            return None
        if node.bl_idname in ('GeometryNodeInputPosition', 'GeometryNodeInputIndex'):
            return (node.bl_idname,)
        if node.bl_idname == 'GeometryNodeInputNamedAttribute' and not self.socket_links.get(node.inputs['Name']):
            return (node.bl_idname, node.data_type, node.inputs['Name'].default_value)
        if node.bl_idname in PURE_PROPERTIES:
            # Nonfinite authored constants are outside this optimization.
            for socket in node.inputs:
                value = getattr(socket, 'default_value', None)
                if isinstance(value, float) and not math.isfinite(value): return None
            return (node.bl_idname, tuple(getattr(node, name) for name in PURE_PROPERTIES[node.bl_idname]))
        return None

    def expressions(self):
        degrees = {node: sum(link.from_node in self.live for link in self.incoming[node]) for node in self.live}
        ready = deque(node for node in self.nodes if node in degrees and degrees[node] == 0)
        tokens = {}; known = {}; aliases = {}; consumers = {}
        while ready:
            node = ready.popleft()
            fields = self.inputs(node, tokens)
            pure = self.pure(node)
            if pure is None:
                tokens[node] = digest(('opaque', node.name, node.bl_idname))
                consumers[node.name] = (node.bl_idname, fields)
            else:
                token = digest((pure, fields)); tokens[node] = token
                representative = known.setdefault(token, node)
                # Multi-input link ordering is deliberately not rewritten.
                if representative != node and not any(link.to_socket.is_multi_input for link in self.outgoing[node]):
                    aliases[node] = representative
            for link in self.outgoing[node]:
                target = link.to_node
                if target not in degrees: continue
                degrees[target] -= 1
                if not degrees[target]: ready.append(target)
        if len(tokens) != len(self.live): raise ValueError('Explicit node cycle cannot be compacted')
        pairs = sorted((a.name, b.name) for a, b in self.pairs if a in self.live)
        return aliases, digest((consumers, pairs))


class NearestQueryIndex(Index):
    """Opt-in sharing of identical nearest-index queries on identical geometry.

    The source geometry, sample-position expression and domain are all part of
    the identity. This does not replace geometric queries with proximity-based
    topology, approximate a result, or combine queries from different sources.
    Native context and saved-scene qualification are required before adoption.
    """
    def pure(self, node):
        if node.bl_idname == 'GeometryNodeSampleNearest' and not node.mute:
            return (node.bl_idname, (node.domain,))
        return super().pure(node)


def disconnect_constant_geometry_branches(tree):
    """Opt-in pruning of literal, unanimated geometry-switch alternatives.

    Keep the switch, its selected link and every consumer link in place. This
    preserves multi-input ordering and zone boundaries. Only an unlinked
    Boolean socket with a fixed authored value permits removing its unselected
    geometry input. Linked runtime conditions are never simplified.
    Call compact() afterwards to remove newly unreachable nodes.
    """
    report = dict(name=tree.name, switches=[])
    if tree.bl_idname != 'GeometryNodeTree':return dict(report, skipped='not a Geometry Nodes tree')
    if tree.animation_data is not None:return dict(report, skipped='animated tree')
    if tree.library is not None:return dict(report, skipped='linked tree')
    if any(node.bl_idname in ('GeometryNodeSimulationInput', 'GeometryNodeSimulationOutput',
                             'GeometryNodeBake') for node in tree.nodes):
        return dict(report, skipped='stateful tree')
    if any(link.is_muted or not link.is_valid for link in tree.links):
        return dict(report, skipped='muted or invalid link')
    for node in tree.nodes:
        if node.bl_idname != 'GeometryNodeSwitch' or node.input_type != 'GEOMETRY' or node.mute:
            continue
        condition = node.inputs['Switch']
        if condition.is_linked:continue
        selected = 'True' if condition.default_value else 'False'
        unused = node.inputs['False' if condition.default_value else 'True']
        if not unused.is_linked:continue
        links = list(unused.links)
        report['switches'].append(dict(node=node.name, selected=selected,
                                      removed=[(link.from_node.name, link.from_socket.identifier) for link in links]))
        for link in links:tree.links.remove(link)
    if report['switches']:tree.update_tag()
    return report


def compact(tree, *, index_type=Index):
    """Return a report; skip animated/stateful or invalid-link trees entirely."""
    before = len(tree.nodes)
    report = dict(name=tree.name, before=before, aliases=0, disconnected=0, after=before)
    if tree.bl_idname != 'GeometryNodeTree':
        return dict(report, skipped='not a Geometry Nodes tree')
    if tree.animation_data is not None:
        return dict(report, skipped='animated tree')
    index = index_type(tree)
    if any(node.bl_idname in ('GeometryNodeSimulationInput', 'GeometryNodeSimulationOutput', 'GeometryNodeBake') for node in index.nodes):
        return dict(report, skipped='stateful tree')
    if any(link.is_muted or not link.is_valid for link in index.links):
        return dict(report, skipped='muted or invalid link')
    aliases, certificate = index.expressions()
    dead = {node for node in index.nodes if node not in index.live and node.bl_idname not in ('NodeGroupInput', 'NodeFrame')}
    removed = dead | set(aliases)
    interface = [(s.identifier, s.name, s.in_out, s.socket_type) for s in tree.interface.items_tree if s.item_type == 'SOCKET']
    for link in index.links:
        if link.from_node not in aliases or link.to_node in removed: continue
        representative = aliases[link.from_node]
        source = representative.outputs[index.output_indices[link.from_socket]]
        target = link.to_socket
        # For normal single-link inputs, Blender's limit check replaces the
        # link without a separate removal/update of the dependent graph.
        # Keep the old operation for any other declared limit; multi-input
        # targets remain excluded above.
        if target.link_limit != 1: tree.links.remove(link)
        tree.links.new(source, target, verify_limits=True)
    # Clear Python references to removed sockets/links before the next audit.
    for node in index.nodes:
        if node in removed: tree.nodes.remove(node)
    interface_after = [(s.identifier, s.name, s.in_out, s.socket_type) for s in tree.interface.items_tree if s.item_type == 'SOCKET']
    if interface != interface_after: raise AssertionError('Field compaction changed the public interface')
    _, after_certificate = index_type(tree).expressions()
    if certificate != after_certificate: raise AssertionError('Field compaction changed a retained consumer expression or zone pairing')
    tree.update_tag()
    report.update(aliases=len(aliases), disconnected=len(dead), after=len(tree.nodes),
                  expression_certificate=certificate, all_outputs_preserved=True)
    return report


def compact_reachable(roots, *, observe=None, index_type=Index):
    """Apply once per reachable group; keep shared datablocks shared."""
    seen = set(); pending = list(roots)
    while pending:
        tree = pending.pop()
        if tree in seen: continue
        seen.add(tree)
        pending.extend(node.node_tree for node in tree.nodes if node.type == 'GROUP' and node.node_tree)
    reports = []
    for tree in sorted(seen, key=lambda group: group.name):
        result = compact(tree,index_type=index_type); reports.append(result)
        if observe is not None: observe(result)
    return reports
